import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十二章","description":"《正易心法》第二十二章——卦义未审，须求变复：变为一爻之变、复为一体之复；以蒙/师、屯/比（一爻之变）与大有/需晋、升/姤复（一体之复）为证，求得不唯辞合、义实通明。","frontmatter":{"title":"正易心法·第二十二章","description":"《正易心法》第二十二章——卦义未审，须求变复：变为一爻之变、复为一体之复；以蒙/师、屯/比（一爻之变）与大有/需晋、升/姤复（一体之复）为证，求得不唯辞合、义实通明。","category":"guide","aliases":["正易心法第二十二章","卦义未审须求变复","义实通明"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-22.md","filePath":"yijing/zheng-yi-xin-fa/chapter-22.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-22.md"},x=p({...c,setup(u){const i=[{id:"z22-01",label:"一、卦义未审须求变复",showLabel:!0,sentences:[["卦义未",{text:"审",glossary:"shen"},"，须求",{text:"变复",glossary:"bianfu"},"。不唯",{text:"辞合",glossary:"cihe"},"，",{text:"义实通明",glossary:"yishiTongming"},"。"]],note:["卦的义理还没有弄清楚时，必须通过变卦和复卦来推求。不只是文辞上符合，义理要真正贯通明白。（**「不唯辞合，义实通明」是全书的方法论总结句**：「辞合」是表层（文辞上说得通，即第三章批评的「依文解义」）；「义实通明」是深层（义理真正贯通，即第一章说的「知落处」）。**读卦的终点不是会背卦辞，而是真见其所以然。**）"]},{id:"z22-02",label:"二、变为一爻之变",showLabel:!0,sentences:[["变为",{text:"一爻之变",glossary:"yiyaoZhibian"},"，复为",{text:"一体之复",glossary:"yitiZhifu"},"。即复变之辞而观之，自然之义，无不与本卦吻合，以见阴阳之气。"]],note:["变，是一爻发生变化；复，是整个上体或下体复归。就着变卦和复卦的辞来看，自然的义理无不与本卦吻合——由此可以见到阴阳之气的运行。（两者是一对：**「变」向前看（一爻动了会怎样），「复」向后看（这一体从哪里来）**。一个卦的义理不只在它自身的辞中，也在它的变卦和复卦中——**三者共同构成完整的义理网络。**）"]},{id:"z22-03",label:"三、一爻之变之例",showLabel:!0,sentences:[["如蒙上九曰：“击蒙。”变为师，上六则云“小人勿用。”屯初九曰：“以贵下贱，大得民也。”变为比，初六则云“有孚比之，无咎。”此一爻之辞合也。"]],note:["比如蒙卦上九说「击蒙」，变为师卦，师卦上六就说「小人勿用」；屯卦初九说「以贵下贱，大得民也」，变为比卦，比卦初六就说「有孚比之，无咎」——这是一爻之变、辞义相合的例子。（两例都说明：**本爻的「刚」一旦改变，义理随之翻转**。蒙上九的「刚」是能「击蒙」的原因，一旦这个刚消失，就成了「小人勿用」；屯初九的「以贵下贱」，正是比卦「有孚比之」的基础。）"]},{id:"z22-04",label:"四、一体之复之例",showLabel:!0,sentences:[["如大有上体复需，有饮食之",{text:"燕",glossary:"yan"},"；下体复晋，有",{text:"昭明",glossary:"zhaoming"},"之德。"]],note:["比如大有卦，上体复归为需卦，有饮食宴乐之象；下体复归为晋卦，有昭明之德。（**用复卦找到义理的两个来源**：大有＝大丰收，其「饮食宴乐」来自需，其「光明昭著」来自晋——一个说内容，一个说品质。）"]},{id:"z22-05",label:"五、升卦之例",showLabel:!0,sentences:[["升上体复姤，姤一阴升；下体复复，复一阳升。此一体之义合也。"]],note:["升卦的上体复归为姤卦，姤是一阴上升；下体复归为复卦，复是一阳上升——这是一体之复、义理相合的例子。（**升卦的「上升」，阴阳两个方向都有根据**：上体得姤（一阴升），下体得复（一阳升）——不是单向的「升」，而是阴阳同升。这就比单看卦辞「元亨，用见大人」精确得多。）"]},{id:"z22-06",label:"六、自然明矣",showLabel:!0,sentences:[["苟卦义未审，能以此求之，自然明矣。"]],note:["如果卦义还没有弄清楚，能用这个方法来推求，自然就明白了。（**本章是全书最后一个方法论工具**：前二十一章建立了象、数、本体论，本章给出读卦的最后一把钥匙——**变复**。它与第十九章的「一卦具八卦」正好配成一对：第十九章是静态的（内含），本章是动态的（变化）。）"]}],o=[{id:"shen",term:"审",pinyin:"shěn",meaning:"审察，弄清楚。「卦义未审」即卦的义理还没有弄清楚。"},{id:"bianfu",term:"变复",pinyin:"biàn fù",meaning:"变卦与复卦。变＝一爻之变，复＝一体之复。读卦的最后一个工具。"},{id:"cihe",term:"辞合",pinyin:"cí hé",meaning:"文辞上符合。这是表层——只做到辞合，仍是第三章批评的「依文解义」。"},{id:"yishiTongming",term:"义实通明",pinyin:"yì shí tōng míng",meaning:"义理真正贯通明白。实＝真实，非空言；通明＝贯通明白。全书方法论的总结句。"},{id:"yiyaoZhibian",term:"一爻之变",pinyin:"yī yáo zhī biàn",meaning:"某一爻发生变化（阴变阳或阳变阴），得到变卦。"},{id:"yitiZhifu",term:"一体之复",pinyin:"yī tǐ zhī fù",meaning:"整个上体（外卦）或下体（内卦）复归其本宫之卦。"},{id:"yan",term:"燕",pinyin:"yàn",meaning:"通「宴」，宴乐。需卦有「饮食宴乐」之义，此处指大有上体复需所得之象。"},{id:"zhaoming",term:"昭明",pinyin:"zhāo míng",meaning:"光明昭著。晋卦有「昭明」之义（晋为日出地上）。"}];return(b,a)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t("",21)),e(l,{colophon:"须求变复 · 一爻之变 · 一体之复 · 义实通明",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十二章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文所引「蒙上九」「师上六」「屯初九」「比初六」诸条辞句随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"一爻之变",pinyin:["yī","yáo"],meaning:"某一爻发生变化（阴↔阳）而得变卦。如蒙上九变则成师，屯初九变则成比。"},{term:"一体之复",pinyin:["yī","tǐ"],meaning:"上体或下体复归其本宫之卦。如大有上体复需（饮食之宴）、下体复晋（昭明之德）。"},{term:"辞合",pinyin:["cí","hé"],meaning:"文辞上说得通。这是表层——只做到辞合，仍是第三章批评的「依文解义」。"},{term:"义实通明",pinyin:["yì","shí"],meaning:"义理真正贯通明白。全书方法论的总结句：读卦的终点不是会背卦辞，而是真见其所以然。"},{term:"静与动",pinyin:["jìng","dòng"],meaning:"第十九章「一卦具八卦」是静态（内含多个卦）；第二十二章「变复」是动态（通过变化连接其他卦）。"}]}),a[3]||(a[3]=t("",27))])}}});export{m as __pageData,x as default};
